def offtopic_live():
    """안건 3개는 모두 논의 전(안건 보드 항목이 없음). 실시간 요약 75개(약 10,000자, 상한 6,000자를 넘음),
    최근 전사 줄 마지막 약 2분 반 (맞장구·확신도 낮은 줄·AI 에게 하는 지시문 포함)."""
    agendas = [{"agendaId": i, "title": t, "status": "NOT_STARTED",
                "decisionPoints": [dp(i * 10 + 1, "NOT_STARTED", "논의 전", [])],
                "summary": [], "opinions": [], "todos": []}
               for i, t in ((1, "출시 일정 확인"), (2, "광고 예산 논의"), (3, "다음 주 할 일 정리"))]
    summary = [{"text": text, "topic": topic, "evidence": [{"start": float(t), "end": float(t + 45)}]}
               for t, topic, text in OFFTOPIC_SUMMARY]
    return {"about": "11/13 주간 회의 진행 중 (합성). 안건과 관계없는 이야기만 약 56분. make_live_meeting.py 로 만듦",
            "meetingId": 120, "meetingStartAt": "2026-11-13T10:00:00", "currentAgendaId": None,
            "liveAgendas": agendas, "recentLines": lines_json([(3000 + k, t, text, kind, low)
                                                               for k, (t, text, kind, low) in enumerate(OFFTOPIC_LINES)]),
            "liveSummary": summary}


def main():
    for name, data in (("live_1112.json", live()), ("live_1112_long.json", long_live()),
                       ("live_1113_offtopic.json", offtopic_live())):
        (HERE / name).write_text(json.dumps(data, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
        print(name, "안건", len(data["liveAgendas"]), "전사 줄", len(data["recentLines"]),
              "글", sum(len(ln["text"]) for ln in data["recentLines"]), "자",
              "실시간 요약", len(data.get("liveSummary") or []), "개",
              sum(len(x["text"]) for x in data.get("liveSummary") or []), "자")


if __name__ == "__main__":
    main()
